import java.nio.file.*;
import java.util.*;
import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.record.FileRecords;
import org.apache.kafka.common.record.RecordBatch;
import org.apache.kafka.common.serialization.ByteArraySerializer;

public class PartitionBatchExperiment {
    static final int COUNT=64;
    static byte[] payload() { byte[] value=new byte[1024];new Random(82917).nextBytes(value);return value; }
    static void produce(String bootstrap,String topic,int partitions) throws Exception {
        Properties p=new Properties();
        p.put("bootstrap.servers",bootstrap);p.put("key.serializer",ByteArraySerializer.class.getName());
        p.put("value.serializer",ByteArraySerializer.class.getName());p.put("acks","all");
        p.put("compression.type","gzip");p.put("batch.size","131072");p.put("linger.ms","1000");
        p.put("delivery.timeout.ms","8000");p.put("request.timeout.ms","2000");p.put("max.block.ms","5000");
        try(KafkaProducer<byte[],byte[]> producer=new KafkaProducer<>(p)) {
            producer.partitionsFor(topic);
            List<java.util.concurrent.Future<RecordMetadata>> acknowledgements=new ArrayList<>();
            for(int n=0;n<COUNT;n++) acknowledgements.add(producer.send(new ProducerRecord<>(topic,n%partitions,null,payload())));
            producer.flush();
            for(var acknowledgement:acknowledgements) acknowledgement.get();
        }
    }
    static String inspect(String directory,String topic,int partitions) throws Exception {
        long batches=0,records=0,bytes=0,payloadBytes=0;
        Set<String> codecs=new HashSet<>();
        for(int partition=0;partition<partitions;partition++) {
            Path root=Path.of(directory,topic+"-"+partition);
            try(var files=Files.list(root)) {
                for(Path path:files.filter(f->f.toString().endsWith(".log")).toList()) {
                    try(FileRecords file=FileRecords.open(path.toFile(),false)) {
                        for(RecordBatch batch:file.batches()) {
                            if(batch.isControlBatch()) continue;
                            batch.ensureValid();batches++;bytes+=batch.sizeInBytes();codecs.add(batch.compressionType().name());
                            for(org.apache.kafka.common.record.Record record:batch) {
                                records++;payloadBytes+=record.valueSize();
                                byte[] actual=new byte[record.value().remaining()];
                                record.value().duplicate().get(actual);
                                if(!Arrays.equals(actual,payload())) throw new AssertionError("payload differs");
                            }
                        }
                    }
                }
            }
        }
        if(records!=COUNT||payloadBytes!=COUNT*1024||!codecs.equals(Set.of("GZIP"))) throw new AssertionError("record/codec evidence differs: "+records+" "+codecs);
        return "{\"partitions\":"+partitions+",\"records\":"+records+",\"batches\":"+batches+",\"payload_bytes\":"+payloadBytes+",\"batch_bytes\":"+bytes+",\"codec\":\"gzip\"}";
    }
    public static void main(String[] args) throws Exception {
        produce(args[0],args[2],1);produce(args[0],args[3],16);
        System.out.println("BATCH_WITNESS {\"one\":"+inspect(args[1],args[2],1)+",\"many\":"+inspect(args[1],args[3],16)+"}");
    }
}
